import sys
from collections import defaultdict

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def main():
    input = sys.stdin.read().split()
    K = int(input[0])
    edges = []
    floor_edges = defaultdict(list)

    index = 1
    for _ in range(K):
        x1, y1, z1, x2, y2, z2 = map(int, input[index:index+6])
        edges.append(((x1, y1, z1), (x2, y2, z2)))
        floor_edges[(x1, y1)].append((x2, y2))
        floor_edges[(x2, y2)].append((x1, y1))
        index += 6

    parent = {point: point for point in set(point for edge in edges for point in edge)}
    rank = {point: 0 for point in parent}

    true_closed_chain = False
    for (x1, y1, z1), (x2, y2) in edges:
        if find(parent, (x1, y1, z1)) == find(parent, (x2, y2, z1)):
            true_closed_chain = True
            break
        union(parent, rank, (x1, y1, z1), (x2, y1, z1))
        union(parent, rank, (x2, y1, z1), (x2, y2, z1))

    floor_visited = set()
    floor_closed_chain = False

    def dfs(node, start, path):
        nonlocal floor_closed_chain
        if node in path:
            floor_closed_chain = True
            return
        floor_visited.add(node)
        path.add(node)
        for neighbor in floor_edges[node]:
            if neighbor not in floor_visited:
                dfs(neighbor, start, path)
        path.remove(node)

    for node in floor_edges:
        if node not in floor_visited:
            dfs(node, node, set())

    print("True closed chains" if true_closed_chain else "No true closed chains")
    print("Floor closed chains" if floor_closed_chain else "No floor closed chains")

main()
